effect.shader:
vec4 u_xlat0;
bvec2 u_xlatb0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec4 u_xlat4;
vec3 u_xlat5;
vec3 u_xlat8;
void main()
{
    u_xlatb0.xy = equal(ivec4(int(_blend_mode)), ivec4(1, 2, 0, 0)).xy;
    u_xlat1 = texture(g_OverlayTex, acScreenNorm.xy);
    u_xlat2 = (-u_xlat1.wxyz) + vec4(1.0, 1.0, 1.0, 1.0);
    u_xlat3 = texture(inputImg, acScreenNorm.xy);
    u_xlat4.xyz = (-u_xlat3.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat8.xyz = (-u_xlat2.yzw) * u_xlat4.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat4 = u_xlat2.xxxx * u_xlat3;
    u_xlat4 = u_xlat1 * u_xlat1.wwww + u_xlat4;
    u_xlat5.xyz = u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1 = u_xlat1 * u_xlat3;
    u_xlat3.xyz = (u_xlatb0.y) ? u_xlat5.xyz : u_xlat8.xyz;
    u_xlat0 = (u_xlatb0.x) ? u_xlat1 : u_xlat3;
    fragColor = (int(_blend_mode) != 0) ? u_xlat0 : u_xlat4;
    return;
}
